import * as React from "react"
import { navigate } from "gatsby"
import Seo from "../components/Seo"
import AuthShell, { AuthLink } from "../components/auth/AuthShell"
import { ArrowRight } from "../components/Icons"
import { NOT_CONFIGURED, configured, humanError, supabase } from "../lib/supabase"
import * as s from "../components/auth/Auth.module.css"

/**
 * Creating an account — MTC-FCS-008.
 *
 * ── IT DOES NOT CONFIRM WHETHER AN ADDRESS IS REGISTERED ───────────────────
 * Success and "already registered" produce the SAME message. A signup form
 * that says "that email is taken" is an oracle: anyone can walk a list of
 * addresses through it and learn which of them have accounts here. The person
 * who genuinely owns the address finds out from their inbox, which is the only
 * place that answer belongs.
 *
 * ── THE MINIMUM IS EIGHT CHARACTERS AND IT SAYS SO UP FRONT ────────────────
 * Checked before submitting, so the rule is not something you discover by
 * failing. Supabase enforces its own minimum too; this one just gets there
 * first with a sentence rather than an API error.
 */
const SignUpPage = () => {
  const [email, setEmail] = React.useState("")
  const [password, setPassword] = React.useState("")
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState("")
  const [sent, setSent] = React.useState(false)

  const available = configured()

  const submit = async e => {
    e.preventDefault()
    if (busy) return
    setError("")

    if (password.length < 8) {
      setError("Please choose a password of at least 8 characters.")
      return
    }

    const client = supabase()
    if (!client) {
      setError(NOT_CONFIGURED)
      return
    }

    setBusy(true)
    const { data, error: err } = await client.auth.signUp({
      email: email.trim(),
      password,
      options: {
        emailRedirectTo:
          typeof window === "undefined" ? undefined : `${window.location.origin}/account`,
      },
    })
    setBusy(false)

    // Both outcomes land here on purpose — see the note above.
    if (err && !/already registered|already exists/i.test(err.message || "")) {
      setError(humanError(err))
      return
    }

    /* ── ALREADY SIGNED IN? THEN SAY SO — MTC-FCS-048 ────────────────────
       Supabase hands back a session immediately when the project is not
       confirming addresses by email, which is where this one is until the
       sending domain is verified. Telling somebody who is already logged in
       to go and open an email that will never arrive is the worst version of
       this screen: they wait, nothing comes, and they conclude the account
       does not exist. Read what actually came back instead of assuming. */
    if (data && data.session) {
      navigate("/account")
      return
    }
    setSent(true)
  }

  return (
    <AuthShell
      title="Create your account"
      lead="You need an account to put a website online and to keep your invoices in one place."
      notice={available ? null : NOT_CONFIGURED}
      footer={
        <>
          Already have one? <AuthLink to="/log-in">Log in</AuthLink>
          {" · "}
          {/* MTC-FCS-035: confirmation emails are the thing most likely to go
              wrong here, so the way out is on the screen that causes it. */}
          <AuthLink to="/help/cannot-log-in">No email arrived?</AuthLink>
        </>
      }
    >
      {sent ? (
        <p className={s.success}>
          If that address is not already registered, a confirmation email is on its way to{" "}
          <strong>{email.trim()}</strong>. Open the link in it to finish setting up your account.
        </p>
      ) : (
        <form onSubmit={submit}>
          <div className={s.fields}>
            <div className={s.field}>
              <label htmlFor="su-email">Email address</label>
              <input
                id="su-email"
                type="email"
                value={email}
                onChange={e => setEmail(e.target.value)}
                autoComplete="email"
                required
                disabled={!available || busy}
              />
            </div>
            <div className={s.field}>
              <label htmlFor="su-password">Password</label>
              <input
                id="su-password"
                type="password"
                value={password}
                onChange={e => setPassword(e.target.value)}
                autoComplete="new-password"
                required
                minLength={8}
                disabled={!available || busy}
              />
              <p className={s.hint}>At least 8 characters.</p>
            </div>
          </div>

          <button
            type="submit"
            className={`btn btn--lg ${s.submit}`}
            disabled={!available || busy || !email.trim() || !password}
          >
            {busy ? "Creating your account…" : "Create account"}
            {!busy && <ArrowRight className="btn__arrow" />}
          </button>

          {error ? <p className={s.error}>{error}</p> : null}
        </form>
      )}
    </AuthShell>
  )
}

export const Head = () => (
  <Seo title="Create an account" description="Create a Free Contractor Services account." />
)

export default SignUpPage
